import React, { useContext, useEffect, useState } from "react";
import { AuthContext } from "../App";
import API from "../api";

export default function Dashboard() {
  const { auth, logout } = useContext(AuthContext);
  const [tasks, setTasks] = useState([]);
  const [title, setTitle] = useState("");
  const [desc, setDesc] = useState("");
  const [due, setDue] = useState("");

  const loadTasks = async () => {
    const res = await API.get("/tasks");
    if (res.data.success) setTasks(res.data.tasks);
  };

  useEffect(() => { loadTasks(); }, []);

  const createTask = async (e) => {
    e.preventDefault();
    await API.post("/tasks", {
      userId: auth.userId,
      title,
      description: desc,
      dueDate: due
    });
    setTitle("");
    setDesc("");
    setDue("");
    loadTasks();
  };

  const update = async (id, progress) => {
    await API.put(`/tasks/${id}`, { progress });
    loadTasks();
  };

  const remove = async (id) => {
    await API.delete(`/tasks/${id}`);
    loadTasks();
  };

  return (
    <div className="app-container">
      <div className="header">
        <h2>Dashboard</h2>
        <button className="btn btn-danger" onClick={logout}>Logout</button>
      </div>

      <h3>Create Task</h3>
      <form className="form" onSubmit={createTask}>
        <input className="input" placeholder="Title" value={title} onChange={(e)=>setTitle(e.target.value)} />
        <input className="input" placeholder="Description" value={desc} onChange={(e)=>setDesc(e.target.value)} />
        <input className="input" type="date" value={due} onChange={(e)=>setDue(e.target.value)} />
        <button className="btn btn-primary">Create</button>
      </form>

      <h3>Your Tasks</h3>
      <div className="tasks">
        {tasks.map(t => (
          <div className="task-card" key={t._id}>
            <div>
              <strong>{t.title}</strong>
              <p>{t.description}</p>
              <p>Due: {t.dueDate ? new Date(t.dueDate).toLocaleDateString() : "—"}</p>
            </div>

            <div>
              <select value={t.progress} onChange={(e)=>update(t._id, e.target.value)}>
                <option value="not-started">Not started</option>
                <option value="in-progress">In Progress</option>
                <option value="completed">Completed</option>
              </select>

              <button className="btn btn-danger" onClick={()=>remove(t._id)}>Delete</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
